import{_ as t,o as a,c as i,O as s}from"./chunks/framework.619bb88b.js";const o="/assets/SpwYUgw.39f6cfed.jpeg",r="/assets/ZsTnjem.26daa4ea.jpeg",n="/assets/f0onbjb.937c6fa6.jpeg",l="/assets/pM31O08.c388aa3a.jpeg",p="/assets/LaJmm4Z.ba262b1d.jpeg",h="/assets/UkLVPci.47f174c3.jpeg",d="/assets/a1j6zHi.61aa57ed.jpeg",c="/assets/UTtd5bG.df6dae2c.jpeg",m="/assets/DNpVzY3.084ea40e.jpeg",g="/assets/4VWqUiZ.0234660a.jpeg",u="/assets/zdj9WUu.78037c5d.png",b="/assets/Bi6Og87.e48b00d8.jpeg",w="/assets/dCNMQaZ.e038d43d.jpeg",f="/assets/vuhsckU.257be370.jpeg",_="/assets/s1eqJiE.390f5469.jpeg",k="/assets/l57tEmr.263e3a75.png",P=JSON.parse('{"title":"How to assemble V4 LED kits","description":"","frontmatter":{},"headers":[],"relativePath":"how_to_build/led_v4_setup.md","filePath":"how_to_build/led_v4_setup.md","lastUpdated":1788722140000}'),E={name:"how_to_build/led_v4_setup.md"};function L(y,e,v,D,q,V){return a(),i("div",null,[...e[0]||(e[0]=[s('<p>Pardon the mess this page is WIP; more docs for other configurations and assembly are in the works.</p><h1 id="how-to-assemble-v4-led-kits" tabindex="-1">How to assemble V4 LED kits <a class="header-anchor" href="#how-to-assemble-v4-led-kits" aria-label="Permalink to &quot;How to assemble V4 LED kits&quot;">​</a></h1><h2 id="v4-mini" tabindex="-1">V4 mini <a class="header-anchor" href="#v4-mini" aria-label="Permalink to &quot;V4 mini&quot;">​</a></h2><h3 id="getting-to-know-your-hardware" tabindex="-1">Getting to know your hardware <a class="header-anchor" href="#getting-to-know-your-hardware" aria-label="Permalink to &quot;Getting to know your hardware&quot;">​</a></h3><p>There are 3 main components of an IR LED kit; the mainboard, LEDs and wires.</p><h3 id="mainboard" tabindex="-1">Mainboard <a class="header-anchor" href="#mainboard" aria-label="Permalink to &quot;Mainboard&quot;">​</a></h3><p>Below is the V4 mini mainboard with major features labeled. <img src="'+o+'" alt="V4mini"><img src="'+r+'" alt="V4mini_back"></p><h3 id="leds" tabindex="-1">LEDs <a class="header-anchor" href="#leds" aria-label="Permalink to &quot;LEDs&quot;">​</a></h3><p>There are 2 different types of LED boards. The one you should have more of are the &quot;N&quot; LEDs. N stands for Normal, these make up 3 of the LEDs per eye. <img src="'+n+'" alt="nLED"><img src="'+l+'" alt="NLEDback"></p><p>The second type is the &quot;E&quot; LEDs. E stands for End as these are put at the end of the LED strand.</p><p><img src="'+p+'" alt="eLED"><img src="'+h+'" alt="eLEDback"></p><p>In future orders the &quot;E&quot; LEDs will be purple for easier distinction. <img src="'+d+'" alt="eLEDpurple"></p><h3 id="wires" tabindex="-1">Wires <a class="header-anchor" href="#wires" aria-label="Permalink to &quot;Wires&quot;">​</a></h3><p>The included wires are a bit special, they have 3 pins on the connectors but only 2 wires are attached. <img src="'+c+'" alt="v4wire"></p><p>This distinction is crucial in assembling a kit as the wires need to go in a specific orientation outlined in the assembly picture which shows the pins without wires as dashes - - -.</p><h3 id="wiring-up-v4-mini" tabindex="-1">Wiring up V4 mini <a class="header-anchor" href="#wiring-up-v4-mini" aria-label="Permalink to &quot;Wiring up V4 mini&quot;">​</a></h3><p>Start by plugging in the long wires to the main board like shown.</p><p><img src="'+m+'" alt="notpluggedr"><img src="'+g+'" alt="pluggedinr"></p><p>Then connect the wires to LEDs in the sequence:</p><p><code>Mainboard -&gt; N LED -&gt; N LED -&gt; N LED -&gt; E LED</code></p><p>You need to <strong>pay very close attention</strong> to the <strong>orientation</strong> of the wires so that the missing wire is facing the correct way. The following image shows a kit fully assembled:</p><p><img src="'+u+'" alt="v4minifull"></p><p>Here is an example of the right eye&#39;s LED strand.</p><p><img src="'+b+'" alt="v4minireye"></p><h2 id="v4-lite" tabindex="-1">V4 Lite <a class="header-anchor" href="#v4-lite" aria-label="Permalink to &quot;V4 Lite&quot;">​</a></h2><h3 id="getting-to-know-v4-lite" tabindex="-1">Getting to know V4 Lite <a class="header-anchor" href="#getting-to-know-v4-lite" aria-label="Permalink to &quot;Getting to know V4 Lite&quot;">​</a></h3><p>V4 Lite is a soldering-required approach to LEDs. There are a few specific caveats to know before assembling and using this hardware.</p><ol><li><p>The board must be supplied with 5V.</p><ul><li>Other voltages may result in darker/non-functioning LEDs.</li></ul></li><li><p>You must change resistors if you change from a single or dual eye setup to the other.</p><ul><li>Not doing so will result in too dim of LEDs or extremely bright LEDs. Ensure you are always using the correct one for your application.</li></ul></li><li><p>Shorts on the main board can result in damaged hardware, dangerously bright LEDs, or nonfunctioning hardware.</p><ul><li>Please ensure there are no shorts (even very small stray solder strands) between any pins or solder joints on the main board or LEDs.</li></ul></li></ol><h3 id="wiring-up-v4-lite" tabindex="-1">Wiring up V4 Lite <a class="header-anchor" href="#wiring-up-v4-lite" aria-label="Permalink to &quot;Wiring up V4 Lite&quot;">​</a></h3><p>First, decide if you want dual eye or single eye operation and pick the appropriate resistor.</p><p><strong><strong>Single Eye:</strong></strong> Use the 130ohm resistor marked with Black, Black, and Gold middle rings:</p><p><img src="'+w+'" alt="v4litesingleeye"></p><p><strong><strong>Dual Eye:</strong></strong> Use the 65ohm resistor marked with Yellow, White and Gold middle rings:</p><p><img src="'+f+'" alt="v4litedualeye"></p><p>Now, solder the resistor on the board (any orientation), and then the black 3 pin voltage regulator (orientation matters, solder on the side with the white outline and have it fit in the outline&#39;s shape).</p><p><img src="'+_+'" alt="v4litemainboardassem"></p><p>Now, wire up the LEDs like shown.</p><p><img src="'+k+'" alt="v4litefullassmb"></p>',38)])])}const x=t(E,[["render",L]]);export{P as __pageData,x as default};
